import numpy as np

# rk4(f, t0, y0, h, n) from lesson 17 is already defined for you.

def vasicek_rhs(t, y, kappa, theta):
    """y = (r, I). Returns the NumPy vector (kappa (theta - r), r)."""
    return np.array([kappa * (theta - y[0]), y[0]])

def discount_exact(r0, kappa, theta, T):
    """exp(-I(T)) from the closed form."""
    I = theta * T + (r0 - theta) * (1 - np.exp(-kappa * T)) / kappa
    return float(np.exp(-I))

def discount_rk4(r0, kappa, theta, T, n):
    """exp(-I(T)) from n RK4 steps on the system."""
    f = lambda t, y: vasicek_rhs(t, y, kappa, theta)
    t, y = rk4(f, 0.0, np.array([r0, 0.0]), T / n, n)
    return float(np.exp(-y[-1][1]))

def steps_to_4dp(method, r0, kappa, theta, T):
    """Smallest n in 1, 2, 4, 8, ... with |method(...) - exact| < 5e-5."""
    exact = discount_exact(r0, kappa, theta, T)
    n = 1
    while abs(method(r0, kappa, theta, T, n) - exact) >= 5e-5:
        n *= 2
    return n
